<?php
$crawl=$crawlerStats; $range=$crawl['range'];
$crawlUrl=fn(array $params=[])=>adminUrl('dashboard',array_merge(['period'=>$range['key']],$params));
$groups=['search'=>'搜索引擎蜘蛛','ai'=>'AI 爬虫与访问','other'=>'其他爬虫'];
$maximum=max([1,...array_values(array_map(fn($point)=>$point['search']+$point['ai']+$point['other'],$crawl['trend']))]);
?>
<section class="panel crawler-dashboard" id="crawler-statistics">
 <div class="crawler-heading"><div><span class="eyebrow">抓取监测</span><h2>搜索蜘蛛与 AI 爬虫</h2></div><a class="button button-outline small" href="<?= e($crawlUrl($crawl['bot']!==''?['bot'=>$crawl['bot']]:[])) ?>#crawler-statistics">刷新数据</a></div>
 <nav class="crawler-periods" aria-label="抓取统计时间范围"><?php foreach(['today'=>'今天','yesterday'=>'昨天','week'=>'本周','month'=>'本月'] as $key=>$label): ?><a data-crawler-period="<?= $key ?>" class="<?= $range['key']===$key?'active':'' ?>" <?= $range['key']===$key?'aria-current="page"':'' ?> href="<?= e(adminUrl('dashboard',['period'=>$key]+($crawl['bot']!==''?['bot'=>$crawl['bot']]:[]))) ?>#crawler-statistics"><?= $label ?></a><?php endforeach ?></nav>
 <p class="crawler-range"><?= e($range['label']) ?>：<?= e(substr($range['start'],0,10)) ?><?= substr($range['start'],0,10)!==$range['last_day']?' 至 '.e($range['last_day']):'' ?> <span>北京时间 · 本周从周一开始</span></p>
 <?php if(!$crawl['available']): ?><div class="notice error">抓取记录暂不可用，请检查数据库迁移与连接。</div><?php else: ?>
 <div class="crawler-metrics"><?php foreach(['visits'=>'总抓取次数','search'=>'搜索蜘蛛','ai'=>'AI 抓取与访问','errors'=>'异常返回（4xx / 5xx）'] as $key=>$label): ?><div class="crawler-metric <?= $key==='errors'?'crawler-error-metric':'' ?>"><span><?= $label ?></span><strong data-crawler-metric="<?= $key ?>"><?= number_format($crawl['totals'][$key]) ?></strong></div><?php endforeach ?></div>
 <div class="crawler-trend-heading"><h3><?= $range['hourly']?'每小时抓取趋势':'每日抓取趋势' ?></h3><div class="crawler-legend"><span class="search">搜索蜘蛛</span><span class="ai">AI</span><span class="other">其他</span></div></div>
 <div class="crawler-chart-scroll"><div class="crawler-chart" role="img" aria-label="<?= e($range['label']) ?>抓取趋势，各时段次数列于柱形图中"><?php foreach($crawl['trend'] as $point): $count=$point['search']+$point['ai']+$point['other']; ?><div class="crawler-chart-column" title="<?= e($point['label']) ?>：搜索蜘蛛 <?= $point['search'] ?> 次，AI <?= $point['ai'] ?> 次，其他 <?= $point['other'] ?> 次"><strong><?= $count ?></strong><div class="crawler-chart-bar"><svg viewBox="0 0 28 120" width="28" height="120" aria-hidden="true"><?php $barBase=120; foreach(['search','ai','other'] as $group): $barHeight=round(120*$point[$group]/$maximum,2); $barBase-=$barHeight; ?><rect class="<?= $group ?>" x="0" y="<?= $barBase ?>" width="28" height="<?= $barHeight ?>"></rect><?php endforeach ?></svg></div><span class="crawler-chart-label"><?= e($point['label']) ?></span></div><?php endforeach ?></div></div>
 <div class="crawler-provider-groups"><?php foreach($groups as $group=>$groupName): ?><section class="crawler-provider-panel"><div class="section-heading"><h3><?= $groupName ?></h3><span><?= number_format($crawl['totals'][$group]) ?> 次</span></div><div class="table-scroll"><table class="crawler-provider-table"><thead><tr><th>爬虫 / 用途</th><th>次数</th><th>地址数</th><th>成功</th><th>跳转</th><th>异常</th><th>最近抓取</th></tr></thead><tbody><?php foreach($crawl['providers'] as $provider): if($provider['group']!==$group) continue; ?><tr data-crawler-provider="<?= e($provider['key']) ?>"><td><a href="<?= e($crawlUrl(['bot'=>$provider['key']])) ?>#crawler-details"><?= e($provider['name']) ?></a><small><?= e($provider['purpose']) ?></small></td><td class="crawler-count"><?= number_format((int)$provider['visits']) ?></td><td><?= number_format((int)$provider['urls']) ?></td><td><?= number_format((int)$provider['successful']) ?></td><td><?= number_format((int)$provider['redirects']) ?></td><td class="<?= $provider['errors']?'crawler-error-text':'' ?>"><?= number_format((int)$provider['errors']) ?></td><td><time><?= $provider['last_visit']?e($provider['last_visit']):'暂无记录' ?></time></td></tr><?php endforeach ?></tbody></table></div></section><?php endforeach ?></div>
 <section class="crawler-details" id="crawler-details"><div class="crawler-heading"><h3>抓取明细 <small><?= number_format($crawl['total']) ?> 条</small></h3><form method="get" action="/dgadmin/index.php"><input type="hidden" name="section" value="dashboard"><input type="hidden" name="period" value="<?= e($range['key']) ?>"><label for="crawler-bot">爬虫</label><select name="bot" id="crawler-bot"><option value="">全部爬虫</option><?php foreach($groups as $group=>$groupName): ?><optgroup label="<?= $groupName ?>"><?php foreach($crawl['catalog'] as $key=>$provider): if($provider['group']!==$group) continue; ?><option value="<?= e((string)$key) ?>" <?= (string)$key===$crawl['bot']?'selected':'' ?>><?= e($provider['name']) ?></option><?php endforeach ?></optgroup><?php endforeach ?></select><button class="button button-outline small">查看</button></form></div>
 <?php if(!$crawl['items']): ?><p class="crawler-empty">所选时间范围<?= $crawl['bot']!==''?'内该爬虫':'' ?>暂无抓取记录。</p><?php else: ?><div class="table-scroll"><table class="crawler-detail-table"><thead><tr><th>抓取时间</th><th>爬虫</th><th>访问地址</th><th>请求</th><th>返回状态</th><th>IP / 标识</th></tr></thead><tbody><?php foreach($crawl['items'] as $visit): ?><tr><td><time><?= e($visit['occurred_at']) ?></time></td><td><?= e($crawl['catalog'][$visit['bot_key']]['name']??$visit['bot_key']) ?></td><td class="crawler-path"><?= e($visit['path']) ?></td><td><?= e($visit['method']) ?></td><td><span class="crawler-status <?= $visit['status_code']>=400?'error':($visit['status_code']>=300?'redirect':'success') ?>"><?= (int)$visit['status_code'] ?></span></td><td><?= e($visit['ip']) ?><details><summary>查看 UA</summary><p><?= e($visit['user_agent']) ?></p></details></td></tr><?php endforeach ?></tbody></table></div><?php endif ?>
 <?php if($crawl['pages']>1): ?><nav class="pagination" aria-label="抓取明细分页"><?php if($crawl['page']>1): ?><a href="<?= e($crawlUrl(['bot'=>$crawl['bot'],'crawler_page'=>$crawl['page']-1])) ?>#crawler-details">上一页</a><?php endif ?><span>第 <?= $crawl['page'] ?> / <?= $crawl['pages'] ?> 页</span><?php if($crawl['page']<$crawl['pages']): ?><a href="<?= e($crawlUrl(['bot'=>$crawl['bot'],'crawler_page'=>$crawl['page']+1])) ?>#crawler-details">下一页</a><?php endif ?></nav><?php endif ?>
 </section>
 <p class="crawler-note">记录始于 <?= e($crawl['started_at']??'启用时') ?>，仅统计到达网站程序的公开页面、robots.txt、站点地图等 GET / HEAD 请求。成功为 2xx，跳转为 3xx，异常为 4xx / 5xx；地址数按不含查询参数的路径去重。按 UA 识别爬虫，身份未经 IP 验证；抓取次数不代表收录量。</p>
 <?php endif ?>
</section>
